mapper.select:
SELECT REQ_TP as "reqTp", LINE_NM as "lineNm", USE_YN as "useYn", UPDT_DT as "updtDt", UPDT_USER_ID as "updtUserId"
  FROM TB_APRV_LINE
 WHERE REQ_TP = #{reqTp}

mapper.update:
UPDATE TB_APRV_DOC_STEP
   SET ACT_STAT = #{actStat}, ACT_CMNT = #{actCmnt, jdbcType=VARCHAR}, ACT_DT = #{now}, ACT_USER_ID = #{actUserId}
 WHERE DOC_ID = #{docId} AND STEP_NO = #{stepNo} AND APRVR_USER_ID = #{aprvrUserId} AND ACT_STAT = 'WAIT'

UPDATE TB_APRV_DOC
   SET DOC_STAT = #{docStat}, CUR_STEP_NO = #{curStepNo}
       , END_DT = #{endDt}
 WHERE DOC_ID = #{docId} AND DOC_STAT = 'PROGRESS'

UPDATE TB_WORD
   SET WORD_ENG_NM = #{engNm}, WORD_ENG_ABRV_NM = #{engAbrvNm}, WORD_DESC = #{desc}, UPDT_DT = #{now}, UPDT_USER_ID = #{userId}
 WHERE WORD_ID = #{targetId} AND APRV_YN = 'N'

mapper.select:
SELECT NOTI_ID as "notiId", NOTI_TP as "notiTp", TITLE as "title", MSG as "msg",
       LINK_TP as "linkTp", LINK_ID as "linkId", READ_YN as "readYn", CRET_DT as "cretDt"
  FROM TB_NOTIFICATION
 WHERE USER_ID = #{userId}
 ORDER BY NOTI_ID DESC
 LIMIT #{limit}

mapper.update:
UPDATE TB_NOTIFICATION SET READ_YN = 'Y'
 WHERE USER_ID = #{userId} AND READ_YN = 'N'

   AND NOTI_ID IN #{n}

mapper.select:
SELECT COUNT(*) FROM TB_ORG
 WHERE USE_YN = 'Y' AND ORG_NM = #{orgNm}
   AND COALESCE(P_ORG_ID, '') = COALESCE(#{pOrgId, jdbcType=VARCHAR}, '')
   AND ORG_ID <> #{orgId}

WITH RECURSIVE T (ORG_ID, DEPTH) AS (
	SELECT ORG_ID, 0 FROM TB_ORG WHERE ORG_ID = #{orgId}
	UNION ALL
	SELECT O.ORG_ID, T.DEPTH + 1 FROM TB_ORG O JOIN T ON O.P_ORG_ID = T.ORG_ID WHERE T.DEPTH < 20 AND O.USE_YN = 'Y'
)
SELECT ORG_ID FROM T

mapper.update:
UPDATE TB_ORG
   SET ORG_NM = #{orgNm}, P_ORG_ID = #{pOrgId, jdbcType=VARCHAR}, HEAD_USER_ID = #{headUserId, jdbcType=VARCHAR},
       SORT_ORD = #{sortOrd}, UPDT_DT = #{now}, UPDT_USER_ID = #{userId}
 WHERE ORG_ID = #{orgId}
